using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace ResearchAgent;

/// <summary>
/// Simulates web search results. Replace with a real search API (Bing, Google, Tavily) in production.
/// </summary>
public static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        // Attempt to use a real search API if configured
        var apiKey = Environment.GetEnvironmentVariable("TAVILY_API_KEY");
        if (!string.IsNullOrEmpty(apiKey))
        {
            return await TavilySearchAsync(query, apiKey);
        }

        // Fallback: simulated search results for demonstration
        return GenerateSimulatedResults(query);
    }

    private static async Task<string> TavilySearchAsync(string query, string apiKey)
    {
        var request = new { api_key = apiKey, query, max_results = 5 };
        var response = await HttpClient.PostAsJsonAsync("https://api.tavily.com/search", request);
        response.EnsureSuccessStatusCode();
        var result = await response.Content.ReadFromJsonAsync<TavilyResponse>();
        if (result?.Results is null || result.Results.Count == 0)
            return "No results found.";

        return string.Join("\n\n", result.Results.Select((r, i) =>
            $"[{i + 1}] {r.Title}\n    {r.Content}\n    Source: {r.Url}"));
    }

    private static string GenerateSimulatedResults(string query)
    {
        // Provide realistic-looking simulated results based on query keywords
        var results = new List<string>
        {
            $"[1] Overview of {query}\n    Recent developments show significant progress in this area. " +
            $"Researchers have published multiple papers highlighting breakthroughs.\n    Source: https://example.com/research/1",

            $"[2] {query} - Latest News\n    Industry experts predict major advances in the coming year. " +
            $"Key players include major tech companies and academic institutions.\n    Source: https://example.com/news/2",

            $"[3] Understanding {query}\n    A comprehensive guide covering fundamentals, current state, " +
            $"and future directions. Includes analysis of recent peer-reviewed publications.\n    Source: https://example.com/guide/3",
        };

        return string.Join("\n\n", results);
    }

    private sealed class TavilyResponse
    {
        [JsonPropertyName("results")]
        public List<TavilyResult> Results { get; set; } = [];
    }

    private sealed class TavilyResult
    {
        [JsonPropertyName("title")]
        public string Title { get; set; } = string.Empty;

        [JsonPropertyName("content")]
        public string Content { get; set; } = string.Empty;

        [JsonPropertyName("url")]
        public string Url { get; set; } = string.Empty;
    }
}

namespace ResearchAgent;

/// <summary>
/// Simple note-taking service that stores research findings in memory.
/// </summary>
public sealed class NoteService
{
    private readonly List<ResearchNote> _notes = [];

    public string AddNote(string title, string content)
    {
        var note = new ResearchNote(title, content, DateTime.UtcNow);
        _notes.Add(note);
        Console.WriteLine($"  📌 Note saved: \"{title}\"");
        return $"Note '{title}' saved successfully. You now have {_notes.Count} note(s).";
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Content}"));
    }

    public IReadOnlyList<string> GetNoteTitles() =>
        _notes.Select(n => n.Title).ToList();
}

internal sealed record ResearchNote(string Title, string Content, DateTime CreatedAt)
{
    public override string ToString() => Title;
}

