builder.Services.AddChatClient(chatBuilder =>
    chatBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<NoteService>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Searches the web for information on a given query. Returns a list of relevant results with titles and snippets."),
    AIFunctionFactory.Create(
        (string title, string content) => noteService.AddNote(title, content),
        "take_note",
        "Saves a research note with a title and content for later summarization."),
    AIFunctionFactory.Create(
        () => noteService.GetAllNotes(),
        "get_notes",
        "Retrieves all saved research notes to review findings so far."),
};

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the latest advances in quantum computing in 2026";

Console.WriteLine($"🔍 Research Agent Starting...");
Console.WriteLine($"📋 Topic: {topic}");
Console.WriteLine(new string('─', 60));

var systemPrompt = $"""
    You are a research agent. Your task is to research the following topic thoroughly:
    "{topic}"

    Follow this process:
    1. Search the web for relevant information (make 2-3 searches with different queries)
    2. Take notes on key findings from each search
    3. Review your notes and produce a final comprehensive summary

    Always take notes before moving to the next search. When you have gathered
    enough information, review your notes and provide a final summary to the user.
    """;

var history = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research this topic: {topic}"),
};

var options = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = tools,
};

var agent = new ChatClientAgent(chatClient, "ResearchAgent");
var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 15,
    Instructions = systemPrompt,
    ModelOptions = options,
};

Console.WriteLine();
int step = 0;

await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        step++;
        Console.WriteLine($"\n📝 [Step {step}]");
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine();
Console.WriteLine(new string('─', 60));
Console.WriteLine("📓 Saved Research Notes:");
foreach (var note in noteService.GetAllNotes())
{
    Console.WriteLine($"  • {note}");
}
Console.WriteLine(new string('─', 60));
Console.WriteLine("✅ Research complete.");

